import{_ as i,a,b as r,c as t,d as n,e as s,f as o,g as l}from"./chunks/Install22b.DDLege5l.js";import{_ as p}from"./chunks/Install17.CwCXrGHM.js";import{_ as d,o as u,c,a3 as h}from"./chunks/framework.g9mfNVRQ.js";const z=JSON.parse('{"title":"Installation","description":"","frontmatter":{"source_hash":"92fd90f109","source_commit":"7a18e7c"},"headers":[],"relativePath":"fr/troubleshoot/install.md","filePath":"fr/troubleshoot/install.md"}'),m={name:"fr/troubleshoot/install.md"};function f(g,e,b,v,_,x){return u(),c("div",null,[...e[0]||(e[0]=[h('<h2 id="my-phone-says-this-app-is-very-dangerous" tabindex="-1">Mon téléphone indique que cette application est très dangereuse <a class="header-anchor" href="#my-phone-says-this-app-is-very-dangerous" aria-label="Permalink to &quot;Mon téléphone indique que cette application est très dangereuse {#my-phone-says-this-app-is-very-dangerous}&quot;">​</a></h2><p>Les versions publiées sur GitHub depuis le <a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer">dépôt officiel</a> sont sûres. Ignorez ce message.</p><img src="'+i+'" style="zoom:75%;"><br><h2 id="i-cannot-find-the-file-i-downloaded" tabindex="-1">Je ne trouve pas le fichier que j&#39;ai téléchargé <a class="header-anchor" href="#i-cannot-find-the-file-i-downloaded" aria-label="Permalink to &quot;Je ne trouve pas le fichier que j&#39;ai téléchargé {#i-cannot-find-the-file-i-downloaded}&quot;">​</a></h2><p>Ouvrez un gestionnaire de fichiers et regardez dans le dossier Téléchargements (Download) de la mémoire interne de votre téléphone : vous devriez y voir un fichier nommé à peu près <code>xDrip-plus-20yymmdd-cccccccc.apk</code></p><br><h2 id="when-i-touch-the-xdrip-apk-it-opens-a-file-list" tabindex="-1">Quand j&#39;appuie sur le fichier .apk de xDrip, une liste de fichiers s&#39;ouvre <a class="header-anchor" href="#when-i-touch-the-xdrip-apk-it-opens-a-file-list" aria-label="Permalink to &quot;Quand j&#39;appuie sur le fichier .apk de xDrip, une liste de fichiers s&#39;ouvre {#when-i-touch-the-xdrip-apk-it-opens-a-file-list}&quot;">​</a></h2><p>Si le fichier xDrip-plus se termine par .zip, renommez-le en .apk et réessayez.</p><p>S&#39;il est impossible de l&#39;ouvrir avec le programme d&#39;installation, essayez avec un <a href="https://play.google.com/store/apps/details?id=com.apkinstaller.ApkInstaller" target="_blank" rel="noreferrer">installateur d&#39;APK</a>.</p><br><h2 id="i-cannot-install-unknown-apps" tabindex="-1">Je ne peux pas installer d&#39;applications inconnues <a class="header-anchor" href="#i-cannot-install-unknown-apps" aria-label="Permalink to &quot;Je ne peux pas installer d&#39;applications inconnues {#i-cannot-install-unknown-apps}&quot;">​</a></h2><img src="'+a+'" style="zoom:75%;"><p>Dans Paramètres Android -&gt; <a href="https://developer.android.com/distribute/marketing-tools/alternative-distribution#unknown-sources" target="_blank" rel="noreferrer">Sécurité</a>, vous devez autoriser l&#39;application que vous utilisez pour ouvrir le fichier téléchargé à installer des fichiers de sources inconnues ; si c&#39;est proposé, choisissez uniquement cette fois-ci.</p><p>Voici l&#39;exemple de Chrome ; vous utilisez peut-être une autre application pour ouvrir le fichier .apk de xDrip.</p><img src="'+r+'" style="zoom:75%;"><br><h2 id="i-cannot-install-the-app" tabindex="-1">Je ne peux pas installer l&#39;application <a class="header-anchor" href="#i-cannot-install-the-app" aria-label="Permalink to &quot;Je ne peux pas installer l&#39;application {#i-cannot-install-the-app}&quot;">​</a></h2><img src="'+t+'" style="zoom:75%;"><p>Vérifiez qu&#39;aucune autre version de xDrip n&#39;est installée : on ne peut mettre à jour ou rétrograder qu&#39;une application du même développeur. Si nécessaire, <a href="./reinstall.html">réinstallez</a> xDrip pour passer de la version officielle à une version dérivée (fork), et inversement.</p><br><h2 id="my-phone-says-this-app-is-unsafe-and-has-been-built-for-an-older-android-version" tabindex="-1"><strong>Mon téléphone indique que cette application n&#39;est pas sûre et a été conçue pour une ancienne version d&#39;Android</strong> <a class="header-anchor" href="#my-phone-says-this-app-is-unsafe-and-has-been-built-for-an-older-android-version" aria-label="Permalink to &quot;**Mon téléphone indique que cette application n&#39;est pas sûre et a été conçue pour une ancienne version d&#39;Android** {#my-phone-says-this-app-is-unsafe-and-has-been-built-for-an-older-android-version}&quot;">​</a></h2><p>Ignorez cet avertissement avec Plus de détails, puis Installer quand même.</p><img src="'+n+'" style="zoom:75%;"><br><h2 id="xdrip-needs-background-location" tabindex="-1">xDrip a besoin de la localisation en arrière-plan <a class="header-anchor" href="#xdrip-needs-background-location" aria-label="Permalink to &quot;xDrip a besoin de la localisation en arrière-plan {#xdrip-needs-background-location}&quot;">​</a></h2><img src="'+s+'" style="zoom:60%;"><p>Pour que xDrip puisse se connecter à un appareil Bluetooth, il doit avoir un <a href="./../install/install.html#enable-location">accès permanent à la localisation</a>.</p><p>Sur les versions récentes d&#39;Android, allez dans Paramètres Android -&gt; Localisation -&gt; Applications -&gt; xDrip ou Paramètres Android -&gt; Applications -&gt; xDrip -&gt; Localisation et vérifiez que Toujours autoriser est sélectionné.</p><img src="'+p+'" style="zoom:80%;"><br><h2 id="xdrip-needs-battery-optimization-whitelisting" tabindex="-1">xDrip doit être exclu de l&#39;optimisation de la batterie <a class="header-anchor" href="#xdrip-needs-battery-optimization-whitelisting" aria-label="Permalink to &quot;xDrip doit être exclu de l&#39;optimisation de la batterie {#xdrip-needs-battery-optimization-whitelisting}&quot;">​</a></h2><img src="'+o+'" style="zoom:60%;"><p>xDrip ne doit pas être optimisé du tout.</p><p>L&#39;emplacement de ce réglage varie selon la marque et la version d&#39;Android ; vous le trouverez généralement dans Paramètres Android -&gt; Applications -&gt; xDrip -&gt; Batterie</p><img src="'+l+'" style="zoom:100%;"><p>Il peut être nécessaire de redémarrer votre téléphone pour appliquer ces changements. Si le message d&#39;avertissement persiste, vérifiez que vous utilisez une version récente de xDrip : mettez-la à jour si nécessaire.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2022.03.27" target="_blank" rel="noreferrer"><em>Dernière modification le 28/3/2022</em></a></p>',39)])])}const D=d(m,[["render",f]]);export{z as __pageData,D as default};
